content.query:
let devices = DeviceInfo
| where TimeGenerated > ago(30d)
| summarize arg_max(TimeGenerated, MachineGroup) by DeviceId, DeviceName
| extend GroupName = iff(isempty(MachineGroup), 'Unassigned', MachineGroup)
| where ('*' in ({DeviceGroup}) or GroupName in ({DeviceGroup}));
let tvmMacro = DeviceTvmSecureConfigurationAssessment
| where TimeGenerated > ago(14d)
| where ConfigurationSubcategory has_any ('Office', 'Macro', 'ASR') or ConfigurationId in ('scid-2501', 'scid-2502', 'scid-2503', 'scid-2504', 'scid-2505', 'scid-2016')
| summarize arg_max(TimeGenerated, IsApplicable, IsCompliant) by DeviceId, ConfigurationId
| where IsApplicable == true
| join kind=inner devices on DeviceId;
let kpiTvm = tvmMacro | summarize Metric = 'Office Macro Policy Compliance % (TVM)', Value = round(100.0 * countif(IsCompliant == true) / max_of(count(), 1), 1);
let kpiWin32Block = DeviceEvents | where TimeGenerated > ago({TimeRange}) | where ActionType == 'AsrOfficeMacroWin32ApiCallsBlocked' | join kind=inner devices on DeviceId | summarize Metric = 'Win32 API Macro Calls Blocked (ML2)', Value = toreal(count());
let kpiWin32Audit = DeviceEvents | where TimeGenerated > ago({TimeRange}) | where ActionType == 'AsrOfficeMacroWin32ApiCallsAudited' | join kind=inner devices on DeviceId | summarize Metric = 'Win32 API Macro Calls Audited (Needs Block)', Value = toreal(count());
let kpiRegTamper = DeviceRegistryEvents | where TimeGenerated > ago({TimeRange}) | where RegistryKey has '\\Office\\' and RegistryValueName in~ ('blockcontentexecutionfrominternet', 'vbawarnings', 'extensionhardening') | join kind=inner devices on DeviceId | summarize Metric = 'Office Macro Registry Changes', Value = toreal(count());
union kpiTvm, kpiWin32Block, kpiWin32Audit, kpiRegTamper
